// Schermata 2: il menu dei clienti PRONTI per il modulo, più l'elenco di quelli accesi ma non pronti, col motivo.
// Pronto = acceso (regola del 01), cartella_drive leggibile, ID Meta validi (regola idMeta del 01), chiave non doppia.
// Esce con «campi» già pronto per la pagina: stringa JSON con ogni $ raddoppiato (n8n inserisce il testo con
// String.replace, che legge $&, $', $` e $$ come comandi; $$ torna $).
const cfg = $('Config').first().json;
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
// Per le schermate finali: dopo sanitizeHtml n8n trasforma ogni «\n» scritto (barra + n) in un a capo; raddoppiare la barra lo evita.
const perSchermo = (s) => esc(s).replace(/\\n/g, '\\\\n');
// Il tipo arriva dal telefono: il server non controlla che sia una delle scelte offerte.
const TIPI = ['post', 'carosello', 'reel', 'storia'];
const tipo = String($('Apri il modulo').first().json.tipo ?? '');
const perPagina = (campi) => JSON.stringify(campi).replace(/\$/g, '$$$$');
const attivo = (v) => /^(si|sì|yes|true|1|x)$/i.test(testo(v));
const unaRiga = (s) => testo(s).replace(/\s+/g, ' ');

// CLIENTI_PROVA vale solo quando il modulo scrive in una scheda di prova, mai nel Calendario vero.
const inProva = testo(cfg.SCHEDA_CALENDARIO) !== 'Calendario';
const clientiProva = inProva ? testo(cfg.CLIENTI_PROVA).toLowerCase().split(/[\s,;|]+/).filter(Boolean) : [];

function idMeta(valore, colonna) {
  if (typeof valore === 'number') {
    if (!Number.isSafeInteger(valore)) return { errore: `${colonna}: Sheets ha arrotondato l'ID, formatta la colonna come testo` };
    return { id: String(valore) };
  }
  const t = testo(valore);
  if (t && !/^\d+$/.test(t)) return { errore: `${colonna} non è un ID valido (solo cifre)` };
  return { id: t };
}
function idCartella(valore) {
  const t = testo(valore);
  const m = t.match(/\/folders\/([A-Za-z0-9_-]{10,})/); // solo link di cartella: un «open?id=» può essere un file
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
}

const righe = $input.all().map((i) => i.json || {}).filter((r) => testo(r.cliente));
const conta = {};
for (const r of righe) { const k = testo(r.cliente).toLowerCase(); conta[k] = (conta[k] || 0) + 1; }

const pronti = [];
const nonPronti = [];
for (const r of righe) {
  const chiave = testo(r.cliente);
  const spaziAiLati = String(r.cliente) !== chiave; // il 01 cerca la chiave così com'è nella cella, senza togliere spazi
  const acceso = attivo(r.attivo);
  const diProva = !acceso && clientiProva.includes(chiave.toLowerCase());
  if (!acceso && !diProva) continue;
  const nome = unaRiga(r.nome_locale) || chiave;
  const motivi = [];
  if (conta[chiave.toLowerCase()] > 1) motivi.push('chiave doppia: il 01 legge solo la prima riga');
  if (spaziAiLati) motivi.push('la chiave cliente ha spazi all\'inizio o alla fine: il 01 non la ritroverebbe');
  const cartella = idCartella(r.cartella_drive);
  if (!testo(r.cartella_drive)) motivi.push('manca il link della cartella Drive nella colonna cartella_drive');
  else if (!cartella) motivi.push('cartella_drive non è il link di una cartella Drive');
  const ig = idMeta(r.ig_user_id, 'ig_user_id');
  const fb = idMeta(r.fb_page_id, 'fb_page_id');
  if (ig.errore) motivi.push(ig.errore);
  if (fb.errore) motivi.push(fb.errore);
  if (!ig.errore && !fb.errore && !ig.id && !fb.id) motivi.push('mancano ig_user_id e fb_page_id: lancia «00 · Attiva cliente»');
  const voce = { cliente: chiave, nome_locale: nome, cartella_id: cartella, ig: ig.id || '', fb: fb.id || '', prova: diProva };
  if (motivi.length) nonPronti.push({ ...voce, motivi });
  else pronti.push({ ...voce, etichetta: `${nome} · ${chiave}${diProva ? ' (prova, spento)' : ''}` });
}

const mappa = {};
for (const p of pronti) {
  const { etichetta, ...dati } = p;
  mappa[etichetta] = dati;
}

const campi = [
  { fieldLabel: 'pagina', fieldName: 'pagina', fieldType: 'hiddenField', fieldValue: 'cliente' },
  {
    fieldLabel: 'Cliente',
    fieldName: 'cliente',
    fieldType: 'dropdown',
    requiredField: true,
    fieldOptions: { values: pronti.map((p) => ({ option: p.etichetta })) },
  },
];
if (nonPronti.length) {
  campi.push({
    fieldType: 'html',
    html: '<p><b>Accesi ma non pronti</b> (non sono nel menu):</p><ul>'
      + nonPronti.map((p) => `<li>${esc(p.nome_locale)} · ${esc(p.cliente)}: ${p.motivi.map(esc).join('; ')}</li>`).join('')
      + '</ul>',
  });
}

const tipoValido = TIPI.includes(tipo);
const messaggioNessuno = !tipoValido ? perSchermo('Tipo di contenuto non valido. Riapri il modulo e scegli post, carosello, reel o storia.') : perSchermo('Nessun cliente è pronto per il modulo.\n\n'
  + (nonPronti.length
    ? 'Accesi ma non pronti:\n' + nonPronti.map((p) => `• ${p.nome_locale} · ${p.cliente}: ${p.motivi.join('; ')}`).join('\n')
    : 'Nella scheda Clienti nessun cliente ha attivo = si.')
  + '\n\nSistema la scheda Clienti e riapri il modulo.'); // la schermata finale mostra HTML: tutto scappato

return [{ json: { campi: perPagina(campi), mappa, pronti: tipoValido ? pronti.length : 0, tipo: tipoValido ? tipo : '', messaggio_nessuno: messaggioNessuno } }];

// Dopo la schermata 2. Se il segno «pagina» non c'è, il modulo è scaduto: n8n ha disattivato la pagina e ha
// passato avanti l'item di prima. Allora ci si ferma in silenzio: nessuna riga, nessun errore, nessuna schermata
// (nessun browser la aspetta), e il 99 non suona per un modulo abbandonato.
const invio = $input.first().json || {};
if (invio.pagina !== 'cliente' || !invio.submittedAt) return [];

const pagina = $('Prepara pagina Cliente').first().json;
const scelta = String(invio.cliente ?? '');
if (!Object.prototype.hasOwnProperty.call(pagina.mappa || {}, scelta)) {
  throw new Error('Modulo 05: il cliente inviato non è tra quelli offerti dalla pagina.');
}
const c = pagina.mappa[scelta];
// L'ID finisce dentro la query di Drive: solo lettere, cifre, trattino e trattino basso.
if (!/^[A-Za-z0-9_-]{10,}$/.test(String(c.cartella_id || ''))) {
  throw new Error('Modulo 05: l\'ID della cartella Drive del cliente non è valido.');
}
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{
  json: {
    ...c,
    nome_html: esc(c.nome_locale), // per la schermata finale e per Telegram (HTML)
    chiave_html: esc(c.cliente),
    q: `'${c.cartella_id}' in parents and mimeType = 'application/vnd.google-apps.folder' and trashed = false`,
  },
}];

// Cerca la sottocartella del modulo (Config.CARTELLA_MODULO, di solito «Da programmare») dentro la cartella del
// cliente. Ignora maiuscole e spazi ai lati. Le altre cartelle (quelle del motore, la radice) non si leggono.
const cfg = $('Config').first().json;
const c = $('Trova la cartella').first().json;
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const nome = testo(cfg.CARTELLA_MODULO) || 'Da programmare';

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\\n/g, '\\\\n'); // dopo sanitizeHtml n8n trasforma «\n» scritto in un a capo: la barra raddoppiata lo evita
// Il link in cartella_drive deve portare a una cartella vera, non a un file e non al cestino
// (lo dice «Controlla la cartella del cliente»; se Drive non la mostra affatto si passa dal ramo errore).
const radice = $('Controlla la cartella del cliente').first().json || {};
if (radice.mimeType !== 'application/vnd.google-apps.folder' || radice.trashed === true) {
  return [{
    json: {
      manca: true,
      messaggio: esc(`Il link nella colonna cartella_drive di ${c.nome_locale} non porta a una cartella Drive`
        + `${radice.trashed === true ? ' (la cartella è nel cestino)' : ' (sembra il link di un file)'}.\n\n`
        + 'Nella scheda Clienti incolla il link della cartella del cliente, quello con /folders/, e riapri il modulo.'),
    },
  }];
}
const cartelle = $input.all().flatMap((i) => (i.json && Array.isArray(i.json.files) ? i.json.files : []));
const trovate = cartelle
  .filter((f) => testo(f.name).toLowerCase() === nome.toLowerCase() && /^[A-Za-z0-9_-]{10,}$/.test(String(f.id || '')))
  .sort((a, b) => String(a.id).localeCompare(String(b.id)));

if (!trovate.length) {
  return [{
    json: {
      manca: true,
      messaggio: esc(`Nella cartella Drive di ${c.nome_locale} non c'è una cartella chiamata «${nome}».\n\n`
        + `Crea dentro la cartella del cliente una cartella chiamata ${nome}, mettici i file pronti e riapri il modulo.`),
    },
  }];
}
const scelta = trovate[0];
return [{
  json: {
    manca: false,
    cartella_id: scelta.id,
    doppie: trovate.length,
    q: `'${scelta.id}' in parents and trashed = false`,
  },
}];

// Schermata 3: i file di «Da programmare» adatti al tipo scelto, con anteprima, e i campi da compilare.
// Toglie cartelle, file di Google, file già nel Calendario (media o copertina), formati che il 01 rifiuta e foto
// oltre 8 MB. Tiene i più recenti (Config.MAX_FILE_PAGINA) e li mostra in ordine di nome.
// «campi» esce come stringa JSON con ogni $ raddoppiato (vedi «Prepara pagina Cliente»).
const cfg = $('Config').first().json;
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const tipo = testo($('Apri il modulo').first().json.tipo).toLowerCase();
const c = $('Trova la cartella').first().json;
const sotto = $('Scegli la sottocartella').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const perPagina = (campi) => JSON.stringify(campi).replace(/\$/g, '$$$$');
// Per le schermate finali: dopo sanitizeHtml n8n trasforma ogni «\n» scritto (barra + n) in un a capo; raddoppiare la barra lo evita.
const perSchermo = (t) => esc(t).replace(/\\n/g, '\\\\n');
const due = (n) => String(n).padStart(2, '0');
const MAX_FILE = Math.max(1, Number(cfg.MAX_FILE_PAGINA) || 60);
const MAX_FOTO_BYTE = 8 * 1024 * 1024; // lo stesso limite del 01
const nomeCartella = testo(cfg.CARTELLA_MODULO) || 'Da programmare';

// --- file già usati nel Calendario ---------------------------------------------------------------
const idDaLink = (voce) => {
  const t = testo(voce);
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
};
const usati = new Set();
for (const item of $input.all()) {
  const r = item.json || {};
  for (const campo of [r.media, r.copertina]) {
    for (const voce of testo(campo).split('|')) { const id = idDaLink(voce); if (id) usati.add(id); }
  }
}

// --- file della cartella ---------------------------------------------------------------------------
const visti = new Set();
const tutti = $('Elenca Da programmare').all()
  .flatMap((i) => (i.json && Array.isArray(i.json.files) ? i.json.files : []))
  .filter((f) => f && f.id && !visti.has(f.id) && visti.add(f.id));

const FORMATI = { 'image/jpeg': 'jpeg', 'image/jpg': 'jpeg', 'image/pjpeg': 'jpeg', 'video/mp4': 'mp4', 'video/quicktime': 'mov' };
const DA_ESTENSIONE = { jpg: 'jpeg', jpeg: 'jpeg', mp4: 'mp4', mov: 'mov' };
const formato = (f) => {
  const mime = testo(f.mimeType).toLowerCase().split(';')[0].trim();
  if (FORMATI[mime]) return FORMATI[mime];
  if (mime === '' || mime === 'application/octet-stream') return DA_ESTENSIONE[testo(f.name).toLowerCase().split('.').pop()] || '';
  return '';
};
const misure = (f) => {
  const im = f.imageMediaMetadata || {};
  const vm = f.videoMediaMetadata || {};
  let w = Number(im.width || vm.width) || 0;
  let h = Number(im.height || vm.height) || 0;
  const rot = Number(im.rotation) || 0;
  if (rot === 1 || rot === 3) [w, h] = [h, w]; // foto verticale dell'iPhone salvata in orizzontale
  const durata = Number(vm.durationMillis) > 0 ? Number(vm.durationMillis) / 1000 : 0;
  return { w, h, durata };
};
const peso = (n) => {
  if (!(n >= 0)) return 'peso non letto';
  if (n < 1024 * 1024) return `${Math.max(1, Math.round(n / 1024))} KB`;
  return `${(n / 1048576).toFixed(1).replace('.', ',')} MB`;
};
// Taglia per caratteri veri (Array.from), non per unità UTF-16: un'emoji tagliata a metà cambierebbe l'etichetta.
const corto = (s, n) => { const c = Array.from(String(s)); return c.length > n ? c.slice(0, n - 1).join('') + '…' : String(s); };

const ACCETTA = { post: ['jpeg'], carosello: ['jpeg'], reel: ['mp4', 'mov'], storia: ['jpeg', 'mp4', 'mov'] }[tipo] || [];
const COSA_SERVE = {
  post: 'una foto JPEG fino a 8 MB',
  carosello: 'almeno 2 foto JPEG, ognuna fino a 8 MB',
  reel: 'un video MP4 o MOV; la copertina, se la vuoi, in JPEG',
  storia: 'una foto JPEG fino a 8 MB oppure un video MP4 o MOV',
}[tipo] || 'un file JPEG, MP4 o MOV';

// Impronta del contenuto (md5Checksum di Drive): la stessa foto caricata due volte ha due ID ma la stessa impronta.
// Una foto risalvata o ritagliata ha un'impronta diversa: quella non si vede.
const impronta = (f) => (/^[0-9a-f]{32}$/i.test(testo(f.md5Checksum)) ? testo(f.md5Checksum).toLowerCase() : '');
const improntaUsata = new Map();
for (const f of tutti) if (usati.has(f.id) && impronta(f)) improntaUsata.set(impronta(f), testo(f.name) || f.id);

const nonProposti = [];
const candidati = [];
// Tutti i JPEG non usati, anche oltre 8 MB: servono alla copertina automatica (il controllo finale blocca quella oltre 8 MB).
const jpegLiberi = [];
// I file «…-copertina.jpg» esclusi, col motivo: così la copertina automatica dice perché non c'è.
const copertineEscluse = {};
const nomeCopertina = (n) => (/-copertina\.jpe?g$/i.test(n) ? n.toLowerCase() : '');
for (const f of tutti) {
  const nome = testo(f.name) || f.id;
  const mime = testo(f.mimeType).toLowerCase();
  const size = Number(f.size);
  if (mime === 'application/vnd.google-apps.folder') { nonProposti.push([nome, 'è una cartella: le sottocartelle non vengono lette']); continue; }
  if (mime.startsWith('application/vnd.google-apps.')) { nonProposti.push([nome, 'è un file di Google (Documento, Foglio…), non una foto né un video']); continue; }
  if (usati.has(f.id)) {
    nonProposti.push([nome, 'già nel Calendario']);
    if (nomeCopertina(nome)) copertineEscluse[nomeCopertina(nome)] = 'è già nel Calendario';
    continue;
  }
  if (improntaUsata.has(impronta(f))) {
    nonProposti.push([nome, `stesso contenuto di «${improntaUsata.get(impronta(f))}», già nel Calendario`]);
    if (nomeCopertina(nome)) copertineEscluse[nomeCopertina(nome)] = `ha lo stesso contenuto di «${improntaUsata.get(impronta(f))}», già nel Calendario`;
    continue;
  }
  const fmt = formato(f);
  if (!fmt) {
    nonProposti.push([nome, `formato non adatto (${mime || 'sconosciuto'}): servono foto JPEG o video MP4/MOV`]);
    if (nomeCopertina(nome)) copertineEscluse[nomeCopertina(nome)] = `c'è, ma non è un JPEG (${mime || 'formato sconosciuto'})`;
    continue;
  }
  const principale = ACCETTA.includes(fmt);
  const copertina = tipo === 'reel' && fmt === 'jpeg';
  if (!principale && !copertina) {
    nonProposti.push([nome, fmt === 'jpeg' ? `è una foto: un ${tipo} vuole un video` : `è un video: un ${tipo} vuole foto JPEG`]);
    continue;
  }
  if (fmt === 'jpeg') jpegLiberi.push({ id: f.id, name: nome, formato: 'jpeg', size: isNaN(size) ? null : size, ...misure(f), modificato: testo(f.modifiedTime), impronta: impronta(f) });
  if (fmt === 'jpeg' && size > MAX_FOTO_BYTE) { nonProposti.push([nome, `foto oltre 8 MB (${peso(size)}): il 01 non la pubblica`]); continue; }
  candidati.push({ id: f.id, name: nome, formato: fmt, size: isNaN(size) ? null : size, ...misure(f), impronta: impronta(f),
    ruolo: principale ? 'file' : 'copertina', modificato: testo(f.modifiedTime),
    thumb: /^https:\/\//.test(testo(f.thumbnailLink)) ? testo(f.thumbnailLink) : '',
    apri: /^https:\/\//.test(testo(f.webViewLink)) ? testo(f.webViewLink) : '' });
}

// Copie identiche fra i file proponibili (dopo formato, peso e «già usato»): ne resta una sola. In ordine vince:
// il nome «…-copertina.jpg»; il video che ha la sua copertina in cartella; il più recente (così il limite della pagina
// lo tiene); il nome senza « (1)» o «Copia di»; l'ordine del nome.
const perNome = (a, b) => a.name.localeCompare(b.name, 'it', { numeric: true, sensitivity: 'base' }) || a.id.localeCompare(b.id);
const eCopertina = (x) => (/-copertina\.jpe?g$/i.test(x.name) ? 1 : 0);
const base = (n) => n.replace(/\.[^.]+$/, '').toLowerCase();
const nomiJpeg = new Set(jpegLiberi.map((x) => x.name.toLowerCase()));
const haCopertina = (x) => (x.formato !== 'jpeg' && (nomiJpeg.has(`${base(x.name)}-copertina.jpg`) || nomiJpeg.has(`${base(x.name)}-copertina.jpeg`)) ? 1 : 0);
const copiaNelNome = (x) => (/ \(\d+\)(\.[^.]+)?$|^(copia di|copy of) /i.test(x.name) ? 1 : 0);
const tenuta = new Map();
for (const x of [...candidati].sort((a, b) => eCopertina(b) - eCopertina(a) || haCopertina(b) - haCopertina(a)
  || b.modificato.localeCompare(a.modificato) || copiaNelNome(a) - copiaNelNome(b) || perNome(a, b))) {
  if (x.impronta && !tenuta.has(x.impronta)) tenuta.set(x.impronta, x);
}
const unici = candidati.filter((x) => {
  if (!x.impronta || tenuta.get(x.impronta) === x) return true;
  nonProposti.push([x.name, `copia identica di «${tenuta.get(x.impronta).name}»: ne propongo una sola`]);
  return false;
});

// Il limite della pagina tiene prima i file principali (i video di un reel), poi le copertine, i più recenti per primi.
unici.sort((a, b) => (a.ruolo === 'file' ? 0 : 1) - (b.ruolo === 'file' ? 0 : 1) || b.modificato.localeCompare(a.modificato));
const fuoriPagina = unici.length > MAX_FILE ? unici.length - MAX_FILE : 0;
const proposti = unici.slice(0, MAX_FILE)
  .sort((a, b) => a.name.localeCompare(b.name, 'it', { numeric: true, sensitivity: 'base' }) || a.id.localeCompare(b.id));
proposti.forEach((x, i) => {
  x.n = i + 1;
  const dettagli = [x.w && x.h ? `${x.w}×${x.h}` : 'misure non lette', peso(x.size)];
  if (x.durata) dettagli.push(`${Math.round(x.durata)} s`);
  // proporzioni: le stesse regole del controllo finale, ma subito, per scegliere a ragion veduta
  if (x.formato === 'jpeg' && x.ruolo === 'file' && x.w && x.h) {
    const r = x.w / x.h;
    if ((tipo === 'post' || tipo === 'carosello') && (r < 0.8 - 0.01 || r > 1.91 + 0.01)) dettagli.push('⚠️ proporzioni fuori: Instagram potrebbe rifiutarla o tagliarla');
    if (tipo === 'storia' && Math.abs(r - 9 / 16) > 0.03) dettagli.push('⚠️ non è verticale 9:16');
  }
  x.dettagli = dettagli.join(' · ');
  x.etichetta = `${due(x.n)} · ${corto(x.name, 80)} · ${x.dettagli}`;
});
const principali = proposti.filter((x) => x.ruolo === 'file');
const copertine = proposti.filter((x) => x.ruolo === 'copertina');
const okFile = tipo === 'carosello' ? principali.length >= 2 : principali.length >= 1;

const togli = ({ etichetta, thumb, apri, modificato, ruolo, impronta: _i, dettagli: _d, ...dati }) => dati;
const mappa = {};
for (const x of principali) mappa[x.etichetta] = togli(x);
const mappaCopertine = {};
for (const x of copertine) mappaCopertine[x.etichetta] = togli(x);

// --- piattaforme possibili per il cliente ----------------------------------------------------------
const PIATTAFORME = [];
if (c.ig && c.fb) PIATTAFORME.push(['Instagram e Facebook', 'ig+fb']);
if (c.ig) PIATTAFORME.push(['Solo Instagram', 'ig']);
if (c.fb) PIATTAFORME.push(['Solo Facebook', 'fb']);
const piattaformeMap = Object.fromEntries(PIATTAFORME);

const COPERTINA_AUTO = 'Automatica: il JPEG che si chiama come il video più «-copertina», se c\'è';
const COPERTINA_NESSUNA = 'Nessuna copertina';
const ORE = [];
for (let h = 0; h < 24; h++) for (let m = 0; m < 60; m += 15) ORE.push(`${due(h)}:${due(m)}`);

// --- testi della pagina ----------------------------------------------------------------------------
const righeAnteprima = proposti.map((x) => '<tr>'
  + `<td><b>${due(x.n)}</b></td>`
  + `<td>${x.thumb ? `<img src="${esc(x.thumb)}" width="96" alt="">` : ''}</td>`
  + `<td>${esc(corto(x.name, 80))}${x.ruolo === 'copertina' ? ' <i>(per la copertina)</i>' : ''}<br>`
  + `${esc(x.dettagli)}`
  + `${x.apri ? ` · <a href="${esc(x.apri)}" target="_blank" rel="noopener noreferrer">apri</a>` : ''}</td>`
  + '</tr>').join('');
const anteprima = `<p><b>File in «${esc(nomeCartella)}» di ${esc(c.nome_locale)}</b></p>`
  + `<table><tr><th>N.</th><th></th><th>File</th></tr>${righeAnteprima}</table>`;

// L'elenco dei non proposti: i «già nel Calendario» diventano una riga sola (crescono a ogni uscita), il resto
// al massimo 30 righe. Le note su file tagliati e cartelle doppie vanno sia nella pagina sia nella schermata finale.
const giaUsati = nonProposti.filter(([, m]) => m === 'già nel Calendario').length;
const altriMotivi = nonProposti.filter(([, m]) => m !== 'già nel Calendario');
const righeNonProposti = altriMotivi.slice(0, 30).map(([n, m]) => `${corto(n, 80)}: ${m}`);
if (altriMotivi.length > 30) righeNonProposti.push(`… e altri ${altriMotivi.length - 30}`);
if (giaUsati) righeNonProposti.push(`${giaUsati} file già nel Calendario (si possono lasciare lì: non vengono riproposti)`);
const noteFuori = [];
if (fuoriPagina) noteFuori.push(`Altri ${fuoriPagina} file non sono in elenco: la pagina ne mostra al massimo ${MAX_FILE}, prima i file principali e poi i più recenti.`);
if (Number(sotto.doppie) > 1) noteFuori.push(`Ci sono ${sotto.doppie} cartelle chiamate «${nomeCartella}»: uso questa, https://drive.google.com/drive/folders/${sotto.cartella_id}. Tienine una sola.`);
const bloccoNonProposti = (righeNonProposti.length || noteFuori.length)
  ? '<p><b>File non proposti e perché</b></p><ul>'
    + righeNonProposti.map((t) => `<li>${esc(t)}</li>`).join('')
    + noteFuori.map((t) => `<li>${esc(t)}</li>`).join('')
    + '</ul>'
  : '';

const opzioni = (lista) => ({ values: lista.map((x) => ({ option: x })) });
const campi = [{ fieldLabel: 'pagina', fieldName: 'pagina', fieldType: 'hiddenField', fieldValue: 'file' }];
campi.push({ fieldType: 'html', html: anteprima });
if (bloccoNonProposti) campi.push({ fieldType: 'html', html: bloccoNonProposti });
if (tipo === 'carosello') {
  campi.push({ fieldLabel: 'Foto del carosello: da 2 a 10, escono nell\'ordine dell\'elenco', fieldName: 'file', fieldType: 'checkbox',
    requiredField: true, fieldOptions: opzioni(principali.map((x) => x.etichetta)),
    limitSelection: 'range', minSelections: 2, maxSelections: Math.min(10, principali.length) });
} else {
  campi.push({ fieldLabel: { post: 'Foto', reel: 'Video', storia: 'Foto o video' }[tipo] || 'File', fieldName: 'file', fieldType: 'radio',
    requiredField: true, fieldOptions: opzioni(principali.map((x) => x.etichetta)) });
}
if (tipo === 'reel') {
  campi.push({ fieldLabel: 'Copertina del reel', fieldName: 'copertina', fieldType: 'radio', requiredField: true,
    fieldOptions: opzioni([COPERTINA_AUTO, COPERTINA_NESSUNA, ...copertine.map((x) => x.etichetta)]), defaultValue: COPERTINA_AUTO });
}
campi.push({ fieldLabel: 'Giorno di uscita', fieldName: 'giorno', fieldType: 'date', requiredField: true });
campi.push({ fieldLabel: 'Ora di uscita', fieldName: 'ora', fieldType: 'dropdown', requiredField: true, fieldOptions: opzioni(ORE) });
campi.push({ fieldLabel: 'Dove esce', fieldName: 'piattaforme', fieldType: 'radio', requiredField: true,
  fieldOptions: opzioni(PIATTAFORME.map(([etichetta]) => etichetta)), ...(PIATTAFORME.length === 1 ? { defaultValue: PIATTAFORME[0][0] } : {}) }); // con più scelte nessuna è già segnata
if (tipo !== 'storia') {
  campi.push({ fieldLabel: 'Indicazioni per Claude: cosa mostra, cosa dire, eventi e offerte decisi dal cliente', fieldName: 'brief',
    fieldType: 'textarea', requiredField: true });
  campi.push({ fieldLabel: 'Primo commento voluto (facoltativo: diventa un\'indicazione per Claude)', fieldName: 'primo_commento',
    fieldType: 'textarea', requiredField: false });
  campi.push({ fieldLabel: 'Persone da taggare (facoltativo: diventa un\'indicazione per Claude)', fieldName: 'tag_persone',
    fieldType: 'text', requiredField: false });
} else {
  campi.push({ fieldLabel: 'Persone da taggare (facoltativo), es. @nome, @nome', fieldName: 'tag_persone', fieldType: 'text', requiredField: false });
}
campi.push({ fieldLabel: 'Note per il team (facoltativo)', fieldName: 'note', fieldType: 'textarea', requiredField: false });

const elencoNonProposti = [...righeNonProposti, ...noteFuori].map((t) => `• ${t}`);
const messaggioNessuno = perSchermo(`Nella cartella «${nomeCartella}» di ${c.nome_locale} non c'è nessun file adatto a un ${tipo}`
  + (tipo === 'carosello' && principali.length === 1 ? ' (ce n\'è una sola foto, ne servono almeno 2)' : '') + '.\n\n'
  + `Cosa va bene: ${COSA_SERVE}.\nCarica i file su Drive, dentro «${nomeCartella}», e riapri il modulo.`
  + (elencoNonProposti.length ? `\n\nFile non proposti e perché:\n${elencoNonProposti.join('\n')}` : '')); // la schermata finale mostra HTML

return [{
  json: {
    campi: perPagina(campi),
    ok_file: okFile,
    mappa,
    mappa_copertine: mappaCopertine,
    jpeg_liberi: jpegLiberi,
    copertine_escluse: copertineEscluse,
    copertina_auto: COPERTINA_AUTO,
    copertina_nessuna: COPERTINA_NESSUNA,
    piattaforme_map: piattaformeMap,
    ore: ORE,
    messaggio_nessuno: messaggioNessuno,
  },
}];

// Dopo la schermata 3. Senza il segno «pagina» = file il modulo è scaduto (vedi «Trova la cartella»):
// fine silenziosa, senza scrivere niente e senza schermate.
const invio = $input.first().json || {};
if (invio.pagina !== 'file' || !invio.submittedAt) return [];
return [{ json: invio }];

// Controlla l'invio della schermata 3 sui dati riletti ADESSO (Clienti, Calendario, scheda di scrittura) e prepara
// la riga del Calendario. Il server di n8n non verifica niente di quello che arriva dal telefono: numero di caselle,
// scelte offerte, formato della data. Per questo qui si ricontrolla tutto.
// Errori → la riga NON si scrive e la schermata li elenca. Avvisi → la riga si scrive e l'avviso va a schermo e su Telegram.
const cfg = $('Config').first().json;
const avvio = $('Apri il modulo').first().json;
const c = $('Trova la cartella').first().json;
const pag = $('Prepara pagina file').first().json;
const invio = $('Modulo ancora valido?').first().json;

const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const due = (n) => String(n).padStart(2, '0');
const has = (o, k) => Object.prototype.hasOwnProperty.call(o || {}, k);
const corto = (s, n) => { const c = Array.from(String(s)); return c.length > n ? c.slice(0, n - 1).join('') + '…' : String(s); };
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const attivo = (v) => /^(si|sì|yes|true|1|x)$/i.test(testo(v));
const siNo = (v, seVuoto) => {
  const t = testo(v).toLowerCase();
  if (!t) return seVuoto;
  return ['si', 'sì', 'yes', 'true', 'vero', '1', 'x', 'ok'].includes(t);
};
const mb = (n) => `${(n / 1048576).toFixed(1).replace('.', ',')} MB`;
const MAX_FOTO_BYTE = 8 * 1024 * 1024;
const MAX_FOTO_CLAUDE = 3.75 * 1024 * 1024;
const MARGINE = Number(cfg.MARGINE_MINIMO_MINUTI) || 30;
const AVVISO_ORE = Number(cfg.AVVISO_ORE) || 3;
const MESI = ['gennaio', 'febbraio', 'marzo', 'aprile', 'maggio', 'giugno', 'luglio', 'agosto', 'settembre', 'ottobre', 'novembre', 'dicembre'];
const GIORNI = ['domenica', 'lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì', 'sabato'];

const tipo = testo(avvio.tipo).toLowerCase();
const scheda = testo(cfg.SCHEDA_CALENDARIO) || 'Calendario';
const inProva = scheda !== 'Calendario';
const clientiProva = inProva ? testo(cfg.CLIENTI_PROVA).toLowerCase().split(/[\s,;|]+/).filter(Boolean) : [];
const indirizzo = testo(cfg.INDIRIZZO_MODULO).replace(/\/form\//, avvio.formMode === 'test' ? '/form-test/' : '/form/');

const errori = [];
const avvisi = [];
// La scheda di scrittura viene dal Config: con un nome sbagliato arriva qui come item d'errore. Conta solo in prova
// (in produzione è il Calendario, già riletto da «Rileggi Calendario» con i suoi tentativi): la riga non si scrive e
// la schermata dice cosa controllare, in italiano.
if (inProva) {
  const e = $('Rileggi scheda di scrittura').all().map((i) => (i.json || {}).error).find(Boolean);
  if (e) {
    const msg = String((e && (e.message || e.description)) || e);
    errori.push(/not found|unable to parse range/i.test(msg)
      ? `non trovo la scheda «${scheda}» nel foglio: controlla il nome della linguetta in basso (spazi e maiuscole compresi)`
      : `Google non mi ha fatto leggere la scheda «${scheda}» (dettaglio: ${corto(msg, 160)})`);
  }
}

// --- ore di Roma -------------------------------------------------------------------------------------
const partiRoma = (ms) => {
  const p = {};
  for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) p[x.type] = x.value;
  return { anno: Number(p.year), mese: Number(p.month), giorno: Number(p.day), ore: Number(p.hour), minuti: Number(p.minute) };
};
// Millisecondi UTC di un'ora di Roma; null se quell'ora non esiste (salto dell'ora legale).
const romaMs = (a, me, g, o, mi) => {
  const base = Date.UTC(a, me - 1, g, o, mi);
  for (const offset of [60, 120]) {
    const t = base - offset * 60000;
    const p = partiRoma(t);
    if (p.anno === a && p.mese === me && p.giorno === g && p.ore === o && p.minuti === mi) return t;
  }
  return null;
};
const leggibile = (ms) => {
  const p = partiRoma(ms);
  const gs = new Date(Date.UTC(p.anno, p.mese - 1, p.giorno)).getUTCDay();
  return `${GIORNI[gs]} ${p.giorno} ${MESI[p.mese - 1]} ${p.anno}, ore ${due(p.ore)}:${due(p.minuti)}`;
};
const giorniNelMese = (a, me) => new Date(Date.UTC(a, me, 0)).getUTCDate();
// Lettura di data_ora delle altre righe: la stessa regola del 04 (testo AAAA-MM-GG HH:MM, GG/MM/AAAA HH:MM, o numero di Sheets).
const chiaveDataOra = (v) => {
  let a; let me; let g; let o; let mi;
  if (typeof v === 'number' && isFinite(v)) {
    const t = new Date(Date.UTC(1899, 11, 30) + Math.round(v * 86400000));
    [a, me, g, o, mi] = [t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate(), t.getUTCHours(), t.getUTCMinutes()];
  } else {
    const s = testo(v).replace(/\s+/g, ' ');
    let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2})[:.](\d{2})/);
    if (m) [a, me, g, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    else {
      m = s.match(/^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4}),? (\d{1,2})[:.](\d{2})/);
      if (!m) return '';
      [g, me, a, o, mi] = [m[1], m[2], m[3], m[4], m[5]].map(Number);
    }
  }
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me) && o >= 0 && o <= 23 && mi >= 0 && mi <= 59)) return '';
  return `${a}-${due(me)}-${due(g)} ${due(o)}:${due(mi)}`;
};

// --- righe già presenti: Calendario e, in prova, la scheda di scrittura --------------------------------
const righe = [...$('Rileggi Calendario').all(), ...(inProva ? $('Rileggi scheda di scrittura').all() : [])]
  .map((i) => i.json || {}).filter((r) => Object.keys(r).length);
const idDaLink = (voce) => {
  const t = testo(voce);
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
};
const usati = new Set();
for (const r of righe) {
  for (const campo of [r.media, r.copertina]) {
    for (const voce of testo(campo).split('|')) { const id = idDaLink(voce); if (id) usati.add(id); }
  }
}

// --- 1 · il cliente, riletto adesso --------------------------------------------------------------------
function idMeta(valore, colonna) {
  if (typeof valore === 'number') {
    if (!Number.isSafeInteger(valore)) { errori.push(`${colonna}: Sheets ha arrotondato l'ID, formatta la colonna come testo`); return ''; }
    return String(valore);
  }
  const t = testo(valore);
  if (t && !/^\d+$/.test(t)) { errori.push(`${colonna} non è un ID valido (solo cifre)`); return ''; }
  return t;
}
const stesseChiavi = $('Rileggi Clienti').all().map((i) => i.json || {})
  .filter((r) => testo(r.cliente) && testo(r.cliente).toLowerCase() === testo(c.cliente).toLowerCase());
let cliente = null;
let igOra = '';
let fbOra = '';
if (!stesseChiavi.length) errori.push(`il cliente «${c.cliente}» non c'è più nella scheda Clienti`);
else if (stesseChiavi.length > 1) errori.push(`la chiave «${c.cliente}» compare ${stesseChiavi.length} volte nella scheda Clienti: il 01 legge solo la prima riga`);
else {
  cliente = stesseChiavi[0];
  if (String(cliente.cliente) !== testo(cliente.cliente)) {
    errori.push(`la chiave «${testo(cliente.cliente)}» ha spazi all'inizio o alla fine nella scheda Clienti: il 01 non la ritroverebbe`);
  }
  if (!attivo(cliente.attivo) && !clientiProva.includes(testo(cliente.cliente).toLowerCase())) {
    errori.push(`il cliente «${testo(cliente.cliente)}» adesso è spento nella scheda Clienti (attivo ≠ si)`);
  }
  igOra = idMeta(cliente.ig_user_id, 'ig_user_id');
  fbOra = idMeta(cliente.fb_page_id, 'fb_page_id');
}
const chiave = cliente ? testo(cliente.cliente) : testo(c.cliente);
const nomeLocale = (cliente && testo(cliente.nome_locale).replace(/\s+/g, ' ')) || c.nome_locale || chiave;

// --- 2, 3, 4, 5, 6 · i file -------------------------------------------------------------------------
const grezzi = Array.isArray(invio.file) ? invio.file : (testo(invio.file) ? [invio.file] : []);
const scelte = [...new Set(grezzi.map((x) => String(x)))];
if (scelte.some((x) => !has(pag.mappa, x))) errori.push('un file inviato non era tra quelli proposti: riapri il modulo');
const file = scelte.filter((x) => has(pag.mappa, x)).map((x) => ({ ...pag.mappa[x], etichetta: x })).sort((a, b) => a.n - b.n);

if (['post', 'reel', 'storia'].includes(tipo) && file.length !== 1) errori.push(`un ${tipo} vuole un file solo, ne sono arrivati ${file.length}`);
if (tipo === 'carosello' && (file.length < 2 || file.length > 10)) errori.push(`un carosello vuole da 2 a 10 foto, ne sono arrivate ${file.length}`);
if (!['post', 'carosello', 'reel', 'storia'].includes(tipo)) errori.push(`tipo «${tipo}» non valido: usa post, carosello, reel o storia`);

const ACCETTA = { post: ['jpeg'], carosello: ['jpeg'], reel: ['mp4', 'mov'], storia: ['jpeg', 'mp4', 'mov'] }[tipo] || [];
for (const f of file) {
  if (!ACCETTA.includes(f.formato)) errori.push(`${f.name}: formato ${f.formato} non adatto a un ${tipo}`);
  if (f.formato === 'jpeg' && Number(f.size) > MAX_FOTO_BYTE) errori.push(`${f.name} pesa ${mb(Number(f.size))}: il 01 accetta foto fino a 8 MB`);
  if (usati.has(f.id)) errori.push(`${f.name} è già nel Calendario: lo stesso file uscirebbe due volte`);
}

let copertina = null;
let senzaCopertina = '';
if (tipo === 'reel') {
  const voce = testo(invio.copertina);
  if (!voce || voce === pag.copertina_auto) {
    const video = file[0];
    if (video) {
      const base = video.name.replace(/\.[^.]+$/, '').toLowerCase();
      const voluti = [`${base}-copertina.jpg`, `${base}-copertina.jpeg`];
      // Copie identiche (stessa impronta md5) contano una volta sola: resta la più recente.
      const perImpronta = new Map();
      for (const x of (pag.jpeg_liberi || []).filter((y) => voluti.includes(testo(y.name).toLowerCase()))
        .sort((a, b) => testo(b.modificato).localeCompare(testo(a.modificato)))) {
        const k = x.impronta || x.id;
        if (!perImpronta.has(k)) perImpronta.set(k, x);
      }
      const trovate = [...perImpronta.values()];
      const nomeVoluto = `${video.name.replace(/\.[^.]+$/, '')}-copertina.jpg`;
      if (trovate.length > 1) {
        errori.push(`ci sono ${trovate.length} file chiamati ${nomeVoluto} (o .jpeg): scegli la copertina a mano`);
      } else if (trovate.length === 1) {
        copertina = trovate[0];
      } else {
        const escluse = pag.copertine_escluse || {};
        const motivo = voluti.map((n) => (has(escluse, n) ? escluse[n] : '')).find(Boolean);
        senzaCopertina = motivo ? `${nomeVoluto} ${motivo}` : `nessun file «${nomeVoluto}» in «${testo(cfg.CARTELLA_MODULO) || 'Da programmare'}»`;
      }
    }
  } else if (voce === pag.copertina_nessuna) {
    senzaCopertina = 'hai scelto «nessuna copertina»';
  } else if (has(pag.mappa_copertine, voce)) {
    copertina = pag.mappa_copertine[voce];
  } else {
    errori.push('la copertina inviata non era tra quelle proposte: riapri il modulo');
  }
  if (copertina) {
    if (copertina.formato && copertina.formato !== 'jpeg') errori.push(`la copertina ${copertina.name} deve essere un JPEG`);
    if (Number(copertina.size) > MAX_FOTO_BYTE) errori.push(`la copertina ${copertina.name} pesa ${mb(Number(copertina.size))}: il 01 accetta foto fino a 8 MB`);
    if (usati.has(copertina.id)) errori.push(`la copertina ${copertina.name} è già nel Calendario`);
  }
}

// --- 7, 8, 9 · giorno e ora --------------------------------------------------------------------------
const giorno = testo(invio.giorno);
const ora = testo(invio.ora);
let quando = null;
const mg = giorno.match(/^(\d{4})-(\d{2})-(\d{2})$/);
const mo = ora.match(/^(\d{2}):(\d{2})$/);
const oreValide = Array.isArray(pag.ore) ? pag.ore : [];
if (!mg) errori.push(`giorno «${corto(giorno, 20)}» non valido: scegli una data dal calendario`);
else if (!mo || !oreValide.includes(ora)) errori.push(`ora «${corto(ora, 10)}» non valida: scegli un'ora dal menu`);
else {
  const [a, me, g] = [Number(mg[1]), Number(mg[2]), Number(mg[3])];
  const [o, mi] = [Number(mo[1]), Number(mo[2])];
  if (!(me >= 1 && me <= 12 && g >= 1 && g <= giorniNelMese(a, me))) errori.push(`il giorno ${giorno} non esiste`);
  else {
    quando = romaMs(a, me, g, o, mi);
    if (quando === null) errori.push(`il ${g}/${me}/${a} alle ${ora} non esiste: è l'ora saltata dal cambio dell'ora legale`);
  }
}
const adesso = Date.now();
if (quando !== null) {
  const minuti = (quando - adesso) / 60000;
  if (minuti < 0) errori.push(`${leggibile(quando)} è già passato`);
  else if (minuti < MARGINE) errori.push(`esce tra meno di ${MARGINE} minuti: il 04 non avrebbe il tempo di preparare il testo`);
  else if (quando - adesso > 365 * 86400000) errori.push(`${leggibile(quando)} è a più di 12 mesi da oggi: controlla l'anno`);
}
const dataOra = mg && mo && quando !== null ? `${mg[1]}-${mg[2]}-${mg[3]} ${ora}` : '';

// --- 10 · piattaforme -------------------------------------------------------------------------------
const vocePiattaforme = testo(invio.piattaforme);
const piattaforme = has(pag.piattaforme_map, vocePiattaforme) ? pag.piattaforme_map[vocePiattaforme] : '';
if (!['ig', 'fb', 'ig+fb'].includes(piattaforme)) errori.push('scegli dove esce: Instagram, Facebook o tutti e due');
else if (cliente) {
  if (piattaforme.includes('ig') && !igOra && !errori.some((e) => e.startsWith('ig_user_id'))) errori.push(`${nomeLocale} non ha ig_user_id nella scheda Clienti: Instagram non è possibile`);
  if (piattaforme.includes('fb') && !fbOra && !errori.some((e) => e.startsWith('fb_page_id'))) errori.push(`${nomeLocale} non ha fb_page_id nella scheda Clienti: Facebook non è possibile`);
}

// --- 11, 12 · brief e tag ---------------------------------------------------------------------------
// «salta controllo ai» non deve arrivare al 01 nemmeno passando dal brief: il 04 copia nelle note
// i suggerimenti di Claude, e Claude potrebbe ripetere la frase. Si toglie ovunque, finché non resta.
const SALTA = /salta\s+controllo\s+ai/gi;
let saltaTolto = false;
const senzaSalta = (v) => {
  let t = testo(v);
  while (new RegExp(SALTA.source, 'i').test(t)) { t = t.replace(SALTA, ' ').replace(/[ \t]{2,}/g, ' ').trim(); saltaTolto = true; }
  return t;
};
const brief = senzaSalta(invio.brief);
const primoCommento = senzaSalta(invio.primo_commento);
const tagGrezzi = senzaSalta(invio.tag_persone);
const MAX_TESTO = 45000; // Google Sheets rifiuta una cella oltre 50.000 caratteri: la scrittura fallirebbe
for (const [nomeCampo, valore] of [['indicazioni per Claude', invio.brief], ['primo commento', invio.primo_commento], ['note', invio.note], ['persone da taggare', invio.tag_persone]]) {
  if (testo(valore).length > MAX_TESTO) errori.push(`${nomeCampo} troppo lunghe: ${testo(valore).length} caratteri, al massimo ${MAX_TESTO}`);
}
if ((brief + primoCommento + tagGrezzi).length > MAX_TESTO) errori.push(`indicazioni, primo commento e tag insieme sono troppo lunghi: al massimo ${MAX_TESTO} caratteri`);
if (saltaTolto) avvisi.push('dalle indicazioni ho tolto «salta controllo AI»: il controllo finale del 01 resta acceso');
if (tipo !== 'storia' && !brief) errori.push('mancano le indicazioni per Claude: senza, il testo uscirebbe generico');
let tagStoria = '';
if (tipo === 'storia' && tagGrezzi) {
  const nomi = [];
  // Si divide come il 01 (| , ; a capo). Lo spazio vale da separatore solo se ogni pezzo inizia con @ («@uno @due»):
  // «Mario Rossi» non deve diventare @mario e @rossi, due account veri di sconosciuti.
  for (const voce of tagGrezzi.split(/[|,;\n]+/).map((s) => s.trim()).filter(Boolean)) {
    const pezzi = voce.split(/\s+/);
    const lista = pezzi.length > 1 && pezzi.every((x) => /^@/.test(x) || /instagram\.com\//i.test(x)) ? pezzi : [voce];
    for (const v of lista) {
      // accetta il link del profilo e quello di una storia; rifiuta i link a post, reel e pagine di Instagram
      const daLink = v.match(/instagram\.com\/(?:stories\/)?([A-Za-z0-9._]+)/i);
      if (daLink && /^(p|reels?|tv|explore|stories|highlights|s|share|_u|accounts|direct)$/i.test(daLink[1])) {
        errori.push(`tag «${corto(v, 60)}» non valido: è il link di un post o di una pagina di Instagram, non di un profilo`);
        continue;
      }
      const nome = (daLink ? daLink[1] : v).replace(/^@+/, '');
      if (!/^[A-Za-z0-9._]{1,30}$/.test(nome)) { errori.push(`tag «${corto(v, 40)}» non valido: un nome utente Instagram (lettere, numeri, punto, trattino basso, senza spazi), separati da virgola`); continue; }
      if (!nomi.includes(nome.toLowerCase())) nomi.push(nome.toLowerCase());
    }
  }
  if (nomi.length > 20) errori.push(`troppe persone da taggare (${nomi.length}, al massimo 20)`);
  tagStoria = nomi.map((n) => `@${n}`).join(', ');
}

// --- 13 · id unico ------------------------------------------------------------------------------------
const idPezzo = (s) => testo(s).replace(/[^A-Za-z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'cliente';
const esecuzione = String($execution.id ?? '').replace(/[^A-Za-z0-9]/g, '') || 'x';
const id = dataOra ? `MO-${idPezzo(chiave)}-${dataOra.slice(0, 10).replace(/-/g, '')}-${ora.replace(':', '')}-${esecuzione}` : '';
if (id && righe.some((r) => testo(r.id).toLowerCase() === id.toLowerCase())) errori.push(`l'id ${id} esiste già: riapri il modulo`);

// --- note: pulizia senza bloccare ------------------------------------------------------------------------
const noteGrezze = testo(invio.note).replace(/\s*\n\s*/g, ' ');
let note = noteGrezze;
const tolto = [];
const regole = [
  [/\[\s*06\s*\]|\[\s*07\s*cartella|\[\s*08\s*:/gi, ' ', 'i segni del motore ([06], [07 cartella, [08:)'],
  [/salta\s+controllo\s+ai/gi, ' ', '«salta controllo AI»: il controllo finale del 01 resta acceso'],
  [/\|/g, '/', 'il segno | (sostituito da /)'],
  [/^\s*(testo AI|testo rifiutato|approvato su Telegram)/i, ' ', 'un inizio che il 04 cancellerebbe'],
];
// Tutte le regole, in giro, finché nessuna trova più niente: togliendo un pezzo se ne potrebbe ricomporre
// un altro (es. «[07salta controllo aicartella» → «[07 cartella»). Ogni passata accorcia il testo o toglie un |.
let cambiato = true;
while (cambiato) {
  cambiato = false;
  note = note.replace(/\s{2,}/g, ' ');
  for (const [re, con, cosa] of regole) {
    if (!new RegExp(re.source, 'i').test(note)) continue;
    note = note.replace(re, con);
    cambiato = true;
    if (!tolto.includes(cosa)) tolto.push(cosa);
  }
}
note = note.replace(/\s{2,}/g, ' ').trim();
if (tolto.length) avvisi.push(`dalle note ho tolto ${tolto.join('; ')}`);

// --- avvisi su file, date, cliente ----------------------------------------------------------------------
const proporzioni = (f, cosa) => {
  if (!f.w || !f.h) { avvisi.push(`misure di ${f.name} non lette: nessun controllo di proporzioni fatto`); return; }
  const r = f.w / f.h;
  if (cosa === 'foto' && (r < 0.8 - 0.01 || r > 1.91 + 0.01)) {
    avvisi.push(`${f.name} è ${f.w}×${f.h}: fuori da 4:5 – 1,91:1, Instagram potrebbe rifiutarla o tagliarla (regola del 01, non verificata su Meta)`);
  }
  if (cosa === 'verticale' && Math.abs(r - 9 / 16) > 0.03) {
    avvisi.push(`${f.name} è ${f.w}×${f.h}: non è verticale 9:16, Instagram potrebbe tagliarla${f.formato === 'jpeg' ? '' : ' (la rotazione dei video non si legge: controllo non verificato)'}`);
  }
};
if (tipo === 'post' || tipo === 'carosello') file.forEach((f) => proporzioni(f, 'foto'));
if (tipo === 'storia' && file[0]) proporzioni(file[0], 'verticale');
if (tipo === 'reel' && file[0]) {
  const v = file[0];
  if (!v.w || !v.h) avvisi.push(`misure di ${v.name} non lette (succede con i video appena caricati): nessun controllo fatto`);
  else if (v.w >= v.h) avvisi.push(`${v.name} è ${v.w}×${v.h}: un reel dovrebbe essere verticale (la rotazione dei video non si legge: controllo non verificato)`);
  if (v.durata && (v.durata < 3 || v.durata > 90)) avvisi.push(`${v.name} dura ${Math.round(v.durata)} secondi: un reel va da 3 a 90 secondi (regola del 01, non verificata su Meta)`);
}
if (tipo === 'storia' && file[0] && file[0].formato !== 'jpeg' && file[0].durata > 60) {
  avvisi.push(`${file[0].name} dura ${Math.round(file[0].durata)} secondi: una storia video va fino a 60 secondi`);
}
const primaFoto = tipo === 'reel' ? copertina : (tipo === 'post' || tipo === 'carosello') ? file[0] : null;
if (primaFoto && Number(primaFoto.size) > MAX_FOTO_CLAUDE) {
  avvisi.push(`${primaFoto.name} pesa ${mb(Number(primaFoto.size))}, oltre 3,75 MB: il 04 non riesce a mostrarla a Claude e il testo nascerà dal solo brief`);
}
if (tipo === 'reel' && !copertina && !errori.some((e) => e.startsWith('la copertina'))) {
  avvisi.push(`reel senza copertina (${senzaCopertina}): il 04 scrive dal solo brief e Instagram sceglie un fotogramma`);
}
let promemoriaStoria = '';
if (quando !== null && !errori.length) {
  if (tipo === 'storia') {
    const p = partiRoma(quando);
    const limite = partiRoma(quando + 2 * 3600000);
    const stessoGiorno = limite.giorno === p.giorno;
    promemoriaStoria = `Approva entro le ${due(p.ore)}:${due(p.minuti)} per uscire puntuale: scrivi «approvato» nella colonna stato. `
      + `Dopo le ${due(limite.ore)}:${due(limite.minuti)}${stessoGiorno ? '' : ` del ${limite.giorno}/${limite.mese}`} non esce più.`;
    avvisi.push(promemoriaStoria);
  } else if (quando - adesso < AVVISO_ORE * 3600000) {
    avvisi.push(`esce tra meno di ${AVVISO_ORE} ore: il testo arriva entro 10 minuti, poi serve il tuo ok in tempo`);
  }
}
if (dataOra) {
  // Le righe «annullato» non escono: non contano per questi avvisi.
  const vive = righe.filter((r) => testo(r.cliente).toLowerCase() === chiave.toLowerCase() && testo(r.stato).toLowerCase() !== 'annullato');
  const elencoId = (rr) => rr.map((r) => testo(r.id) || '?').join(', ');
  const stessaOra = vive.filter((r) => chiaveDataOra(r.data_ora) === dataOra);
  if (stessaOra.length) avvisi.push(`c'è già un'altra riga di ${nomeLocale} alla stessa ora (id ${elencoId(stessaOra)})`);
  if (tipo === 'storia' || tipo === 'reel') {
    const stessoGiorno = vive.filter((r) => testo(r.tipo).toLowerCase() === tipo && chiaveDataOra(r.data_ora).slice(0, 10) === dataOra.slice(0, 10) && !stessaOra.includes(r));
    if (stessoGiorno.length) avvisi.push(`c'è già un'altra ${tipo === 'storia' ? 'storia' : 'riga reel'} di ${nomeLocale} quel giorno (id ${elencoId(stessoGiorno)})`);
  }
}
const senzaOk = cliente && tipo !== 'storia' && !siNo(cliente.approvazione_testi, true);
if (senzaOk) avvisi.push('per questo cliente approvazione_testi = no: uscirà senza il tuo ok, dopo il solo controllo AI del 01');

// --- la riga, 20 colonne ------------------------------------------------------------------------------------
const linkDrive = (x) => `https://drive.google.com/file/d/${x.id}/view`;
const righeBrief = [brief];
if (tipo !== 'storia' && primoCommento) righeBrief.push(`Primo commento voluto: ${primoCommento}`);
if (tipo !== 'storia' && tagGrezzi) righeBrief.push(`Da taggare: ${tagGrezzi}`);
const stato = tipo === 'storia' ? 'da_approvare' : 'da_scrivere';
const riga = {
  id,
  cliente: chiave,
  tipo,
  piattaforme,
  data_ora: dataOra,
  didascalia: '',
  primo_commento: '',
  media: file.map(linkDrive).join(' | '),
  copertina: copertina ? linkDrive(copertina) : '',
  stato,
  esecuzione: '',
  link_ig: '',
  link_fb: '',
  pubblicato_il: '',
  errore: '',
  note: `[modulo]${note ? ' ' + note : ''}`,
  brief: tipo === 'storia' ? '' : righeBrief.filter(Boolean).join('\n'),
  tag_persone: tipo === 'storia' ? tagStoria : '',
  collaboratori: '',
  luogo: '',
};

// --- testi per lo schermo e per Telegram ------------------------------------------------------------------
const NOMI_PIATTAFORME = { ig: 'Instagram', fb: 'Facebook', 'ig+fb': 'Instagram e Facebook' };
const riepilogo = [
  `Cliente: ${nomeLocale} (${chiave})`,
  `Tipo: ${tipo}`,
  `Uscita: ${quando !== null ? leggibile(quando) : `${giorno || '?'} ${ora || '?'}`}`,
  `Dove: ${NOMI_PIATTAFORME[piattaforme] || vocePiattaforme || '?'}`,
  `File: ${file.length ? file.map((f) => f.etichetta).join('; ') : grezzi.map(String).join('; ') || 'nessuno'}`,
];
if (tipo === 'reel') riepilogo.push(`Copertina: ${copertina ? copertina.name : 'nessuna'}`);
const datiScritti = [];
if (brief) datiScritti.push(`Indicazioni per Claude: ${brief}`);
if (primoCommento) datiScritti.push(`Primo commento voluto: ${primoCommento}`);
if (tagGrezzi) datiScritti.push(`Persone da taggare: ${tagGrezzi}`);
if (testo(invio.note)) datiScritti.push(`Note: ${testo(invio.note)}`);
const prossimo = tipo === 'storia'
  ? 'Stato: da_approvare. La storia esce solo dopo il tuo «approvato» nel foglio.'
  : senzaOk
    ? 'Stato: da_scrivere. Claude scrive il testo entro 10 minuti; se passa i controlli esce senza il tuo ok.'
    : 'Stato: da_scrivere. Claude scrive il testo entro 10 minuti e ti chiede l\'ok su Telegram.';
const intestazioneProva = inProva ? `PROVA: riga scritta nella scheda «${scheda}», non nel Calendario vero.\n\n` : '';

const ok = errori.length === 0;
// La schermata finale mostra il testo come HTML (sanitizeHtml toglie i tag): tutto quello che viene dal foglio,
// da Drive o dal telefono va scappato, così «Promo <solo oggi>» resta leggibile e copiabile.
const schermoTesto = ok
  ? `${intestazioneProva}La riga è nel Calendario (id ${id}).\n\n${riepilogo.join('\n')}\n${prossimo}`
    + (avvisi.length ? `\n\nDa sapere:\n• ${avvisi.join('\n• ')}` : '')
  : `La riga NON è stata scritta.\n\nDa correggere:\n• ${errori.join('\n• ')}\n\n`
    + `Quello che avevi scelto e scritto, da copiare:\n${riepilogo.join('\n')}`
    + (datiScritti.length ? `\n${datiScritti.join('\n')}` : '');
const testoSchermo = esc(schermoTesto).replace(/\\n/g, '\\\\n') // «\n» scritto: n8n lo trasformerebbe in un a capo
  + (ok ? '' : (/^https:\/\//.test(indirizzo)
    ? `\n\nPer ricominciare riapri il modulo: <a href="${esc(indirizzo)}">${esc(indirizzo)}</a>`
    : '\n\nPer ricominciare riapri il modulo.'));
// Telegram in modalità HTML: si scappano & < > (un trattino basso in modalità Markdown farebbe rifiutare il messaggio).
// Si taglia il testo in chiaro PRIMA di scappare, per non spezzare un «&amp;» a metà.
const chiaroTelegram = `${riepilogo.join('\n')}\n${prossimo}`
  + (brief ? `\nIndicazioni: ${corto(brief, 300)}` : '')
  + (avvisi.length ? `\n\nDa sapere:\n• ${avvisi.join('\n• ')}` : '');
let lunghezza = 3600;
while (lunghezza > 400 && esc(corto(chiaroTelegram, lunghezza)).length > 3900) lunghezza -= 200;
const testoTelegram = `<b>${inProva ? 'PROVA · ' : ''}📝 Modulo 05: nuova riga nel Calendario</b>\n${esc(corto(chiaroTelegram, lunghezza))}`;

return [{
  json: {
    ok,
    errori,
    avvisi,
    riga,
    testo_schermo: testoSchermo,
    testo_telegram: testoTelegram,
  },
}];

// 15 secondi dopo la scrittura si rilegge la scheda e si cerca la riga per id (richiesta della sessione motore).
// Avvisa, senza cambiare niente, in tre casi: la riga non c'è (potrebbe essere stata sovrascritta da un'altra aggiunta
// fatta nello stesso istante), il media è cambiato, lo stesso file è anche in un'altra riga (due invii insieme).
// Lo stato non si confronta: il 04 può averlo già portato a in_scrittura.
const p = $('Controlla e prepara la riga').first().json;
const riga = p.riga || {};
const testo = (v) => (v === null || v === undefined ? '' : String(v)).trim();
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const idDaLink = (voce) => {
  const t = testo(voce);
  const m = t.match(/\/d\/([A-Za-z0-9_-]{10,})/) || t.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  if (/^[A-Za-z0-9_-]{10,}$/.test(t)) return t;
  return '';
};
const idFile = (r) => [r.media, r.copertina].flatMap((campo) => testo(campo).split('|')).map(idDaLink).filter(Boolean);

// Solo le righe lette davvero dal foglio: la lettura di Sheets aggiunge sempre row_number. Se la rilettura fallisce,
// n8n (onError continueRegularOutput) passa avanti l'item in ingresso, cioè la riga appena scritta, senza row_number:
// confrontarla con sé stessa direbbe «tutto a posto».
const lette = $input.all().map((i) => i.json || {}).filter((r) => Object.prototype.hasOwnProperty.call(r, 'row_number'));
const letturaFallita = lette.length === 0;
const scheda = String($('Config').first().json.SCHEDA_CALENDARIO || 'Calendario');
let rigaMancante = false;
const problemi = [];
if (letturaFallita) {
  problemi.push('non sono riuscito a rileggere il foglio dopo la scrittura: controlla tu che la riga ci sia');
} else {
  const stesse = lette.filter((r) => testo(r.id) === riga.id);
  if (!stesse.length) {
    rigaMancante = true;
    problemi.push(`la riga ${riga.id} non c'è nella scheda «${scheda}» 15 secondi dopo la scrittura: forse è stata sovrascritta. Controlla la scheda e, se manca, riapri il modulo`);
  } else {
    if (stesse.length > 1) problemi.push(`l'id ${riga.id} compare ${stesse.length} volte nel foglio`);
    if (testo(stesse[0].media) !== testo(riga.media)) problemi.push(`il media della riga ${riga.id} è cambiato subito dopo la scrittura: controllala`);
  }
  const miei = new Set(idFile(riga));
  const altre = lette.filter((r) => testo(r.id) !== riga.id && testo(r.stato).toLowerCase() !== 'annullato' && idFile(r).some((x) => miei.has(x)));
  if (altre.length) {
    problemi.push(`lo stesso file è anche nella riga ${altre.map((r) => testo(r.id) || '?').join(', ')}: uscirebbe due volte. Annullane una mettendo stato = annullato`);
  }
}

// Se la riga è sparita, il riepilogo del controllo («La riga è nel Calendario», «Claude scrive il testo…») non è più vero:
// si corregge la prima frase e si toglie la riga dello stato, a schermo e su Telegram.
const togliStato = (t) => String(t || '').replace(/\nStato: [^\n]*/, '');
const schermoRiepilogo = rigaMancante
  ? togliStato(p.testo_schermo).replace(/La riga è nel Calendario \(id ([A-Za-z0-9-]*)\)\./, 'La riga $1 era stata scritta ma ora non c\'è: per ora NON è in programma. Riapri il modulo per scriverla di nuovo.')
  : String(p.testo_schermo || '');
const telegramRiepilogo = rigaMancante
  ? togliStato(p.testo_telegram).replace('📝 Modulo 05: nuova riga nel Calendario</b>', '⚠️ Modulo 05: riga scritta e poi sparita</b>')
  : String(p.testo_telegram || '');
// Un problema si legge per primo, prima del riepilogo.
const bloccoTelegram = problemi.length ? `⚠️ <b>Controllo dopo la scrittura</b>\n• ${problemi.map(esc).join('\n• ')}` : '';
// Telegram accetta 4096 caratteri: si taglia a fine riga (i tag <b> stanno sempre su una riga sola).
let telegram = bloccoTelegram ? `${bloccoTelegram}\n\n${telegramRiepilogo}` : telegramRiepilogo;
if (telegram.length > 4000) {
  telegram = telegram.slice(0, 4000);
  telegram = telegram.slice(0, telegram.lastIndexOf('\n'));
}
const bloccoSchermo = problemi.length ? esc(`Controllo dopo la scrittura:\n• ${problemi.join('\n• ')}\n\n`).replace(/\\n/g, '\\\\n') : '';
return [{
  json: {
    problemi,
    testo_telegram: telegram,
    extra_schermo: bloccoSchermo,
    testo_schermo: `${bloccoSchermo}${schermoRiepilogo}`,
    riga_mancante: rigaMancante,
  },
}];

